inline int rf_predict_tree(const RFNode* tree, float f[RF_N_FEATURES]) {
  int32_t node = 0;
  while (true) {
    RFNode n;
    memcpy_P(&n, &tree[node], sizeof(RFNode));
    if (n.leaf >= 0) return n.leaf;
    node = (f[n.feature] <= n.threshold) ? n.left : n.right;
  }
}

inline int rf_predict(float f[RF_N_FEATURES], float* confidence = nullptr) {
  uint16_t votes0 = 0, votes1 = 0;
  for (uint16_t t = 0; t < RF_N_TREES; ++t) {
    const RFNode* tree = (const RFNode*)pgm_read_ptr(&rf_forest[t]);
    int c = rf_predict_tree(tree, f);
    if (c == 0) ++votes0; else ++votes1;
  }
  uint16_t best = (votes1 >= votes0) ? votes1 : votes0;
  if (confidence) *confidence = 100.0f * ((float)best / (float)RF_N_TREES);
  return (votes1 >= votes0) ? 1 : 0;
}
